fn single(x: &[i32], y: &[i32]) -> Vec<i32> {
    // Pre-allocate a vector with the combined capacity of both slices
    let mut result = Vec::with_capacity(x.len() + y.len());
    // Append all elements from the first slice
    result.extend_from_slice(x);
    // Append all elements from the second slice
    result.extend_from_slice(y);
    result
}

